import { HB_ROMAN } from '../../core';
import { agreement, latestRating } from '../../data/export';
import { useApp } from '../../data/store';
import { AppBar, Notice } from '../components/common';
import { Icon } from '../icons';
import { dayLabel, fmtDate } from '../labels';

const f2 = (x: number | null) => (x === null ? '–' : x.toFixed(2));

export function Research() {
  const { sessions, ratings } = useApp();
  const ag = agreement(sessions, ratings);
  const scored = sessions.filter((s) => s.analysis.scores);
  return (
    <>
      <AppBar title="연구 도구" sub="임상 유효성 평가 지원" onBack />
      <main class="main">
        <div class="card tight">
          <Notice>
            <span class="small">
              같은 방문에서 의료진이 <b>앱 결과를 보지 않은 상태로</b> House–Brackmann·Sunnybrook을 평가해 입력하면, 앱 추정치와의 일치도를
              계산합니다.
            </span>
          </Notice>
        </div>

        <div class="section-title">일치도 (앱 추정 vs 임상가)</div>
        <div class="card">
          <div class="tiles">
            <div class="tile">
              <span class="label">Sunnybrook ICC(2,1) · n={ag.nComposite}</span>
              <span class="value tabular">{f2(ag.iccComposite)}</span>
            </div>
            <div class="tile">
              <span class="label">HB 가중 κ(이차) · n={ag.nHb}</span>
              <span class="value tabular">{f2(ag.kappaHb)}</span>
            </div>
            <div class="tile">
              <span class="label">HB 완전 일치 / ±1 등급</span>
              <span class="value tabular">
                {ag.exactHb === null ? '–' : `${Math.round(ag.exactHb * 100)}%`}
                <small>{ag.withinOneHb === null ? '' : ` / ${Math.round(ag.withinOneHb * 100)}%`}</small>
              </span>
            </div>
            <div class="tile">
              <span class="label">Bland–Altman 편향 (95% LoA)</span>
              <span class="value tabular" style={{ fontSize: '18px' }}>
                {ag.ba ? `${ag.ba.bias.toFixed(1)} (${ag.ba.lower.toFixed(1)}~${ag.ba.upper.toFixed(1)})` : '–'}
              </span>
            </div>
          </div>
          <p class="xsmall muted">각 지표는 짝지어진 평가가 3건 이상일 때 계산됩니다. 연구 분석에는 CSV 내보내기를 사용하세요.</p>
        </div>

        <div class="section-title">임상가 평가 입력</div>
        <div class="card tight">
          {scored.length === 0 && <p class="small muted">완료된 평가가 없습니다.</p>}
          <div class="list">
            {[...scored].reverse().map((s) => {
              const r = latestRating(ratings, s.id);
              return (
                <a class="list-item" href={`#/rate/${s.id}`}>
                  <div class="grow">
                    <div>
                      {fmtDate(s.createdAt)} <span class="small muted">· {dayLabel(s.daysSinceOnset)}</span>
                    </div>
                    <div class="xsmall ink2">
                      {r
                        ? `입력됨 · ${r.raterId} · HB ${r.houseBrackmann ? HB_ROMAN[r.houseBrackmann] : '–'} · SB ${r.sunnybrookComposite ?? '–'}`
                        : '미입력'}
                    </div>
                  </div>
                  <Icon name="chev" class="chev" />
                </a>
              );
            })}
          </div>
        </div>

        <div class="section-title">재활 동작 그림 검수</div>
        <a class="card tight" href="#/anim-review" style={{ textDecoration: 'none', color: 'inherit' }}>
          <div class="row">
            <Icon name="activity" />
            <div class="grow">
              <div>동작 그림 검수표</div>
              <div class="xsmall muted">모든 운동의 준비·유지·풀기 장면을 한 화면에서 확인 (치료사 검수용)</div>
            </div>
            <Icon name="chev" class="chev" />
          </div>
        </a>

        <a class="card tight" href="#/pose-lab" style={{ textDecoration: 'none', color: 'inherit' }}>
          <div class="row">
            <Icon name="image" />
            <div class="grow">
              <div>레퍼런스 대조</div>
              <div class="xsmall muted">참고 영상 캡처와 같은 단계의 2D·3D 그림을 나란히 비교 (캡처는 로컬 전용)</div>
            </div>
            <Icon name="chev" class="chev" />
          </div>
        </a>

        <div class="section-title">표준 사진 세트 분석</div>
        <a class="card tight" href="#/photo" style={{ textDecoration: 'none', color: 'inherit' }}>
          <div class="row">
            <Icon name="image" />
            <div class="grow">
              <div>사진 6장으로 평가</div>
              <div class="xsmall muted">표준화된 임상 사진(안정 + 5개 동작)을 같은 알고리즘으로 분석합니다. 사진은 저장되지 않습니다.</div>
            </div>
            <Icon name="chev" class="chev" />
          </div>
        </a>
      </main>
    </>
  );
}
